solution.code:
// 方法 1: 使用 let
for (let i = 0; i < 5; i++) {
  setTimeout(() => {
    console.log(i);  // 0,1,2,3,4
  }, 1000);
}

// 方法 2: 使用 IIFE
for (var i = 0; i < 5; i++) {
  (function(j) {
    setTimeout(() => {
      console.log(j);
    }, 1000);
  })(i);
}
